module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for inputs corresponding to 2, 7, 15
    // Binary representations:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1
    // SOP expression: (a' & b' & c & d') + (a' & b & c & d) + (a & b & c & d)

    assign out_sop = 
        (~a & ~b & c & ~d) | 
        (~a & b & c & d) | 
        (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 1 for all inputs except 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations of excluded values:
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110
    // POS expression: (a + b + c + d') & (a + b + c' + d) & (a + b' + c + d) & (a + b' + c' + d') & (a' + b + c + d') & (a' + b + c' + d) & (a' + b' + c + d) & (a' + b' + c' + d)

    assign out_pos = 
        (a | b | c | ~d) &
        (a | b | ~c | d) &
        (a | ~b | c | d) &
        (a | ~b | ~c | ~d) &
        (~a | b | c | ~d) &
        (~a | b | ~c | d) &
        (~a | ~b | c | d) &
        (~a | ~b | ~c | ~d);

endmodule

