module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // State transition logic
    // next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
    //              (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
    //              (state == 4'b0100) ? (in ? 4'b0001 : 4'b1000) :
    //              (state == 4'b1000) ? (in ? 4'b0100 : 4'b0010) : 4'b0000;

    // Output logic
    // out = (state == 4'b1000) ? 1 : 0;

    // Implementing the above using case statements for clarity
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001;
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100;
            4'b0100: next_state = (in) ? 4'b0001 : 4'b1000;
            4'b1000: next_state = (in) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase

        case (state)
            4'b1000: out = 1;
            default: out = 0;
        endcase
    end

endmodule

