        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001;
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100;
            4'b0100: next_state = (in) ? 4'b0001 : 4'b1000;
            4'b1000: next_state = (in) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase

        case (state)
            4'b1000: out = 1;
            default: out = 0;
        endcase
    end

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for inputs corresponding to 2, 7, 15
    // Binary representations:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1
    assign out_sop = 
        (~a & ~b & c & ~d) | 
        (~a & b & c & d) | 
        (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 1 for inputs corresponding to 2, 7, 15
    // Excluded values: 0, 1, 4, 5, 6, 9, 10, 13, 14
    // We derive the POS form by finding the complement of the SOP expression
    // The SOP expression is: (~a & ~b & c & ~d) + (~a & b & c & d) + (a & b & c & d)
    // The complement is the product of sums of the excluded minterms

    // Excluded minterms (binary values not allowed):
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110

    // The POS expression is the product of the following sums:
    // (a + b + c + d')  // excludes 0, 1, 4, 5
    // (a + b + c' + d)  // excludes 6, 10, 14
    // (a + b' + c + d)  // excludes 9, 13
    // (a + b' + c' + d') // excludes 10, 14
    // (~a + b + c + d') // excludes 2, 7, 15
    // (~a + b + c' + d) // excludes 2, 7, 15
    // (~a + b' + c + d) // excludes 2, 7, 15
    // (~a + b' + c' + d') // excludes 2, 7, 15

    // The correct POS expression is:
    assign out_pos = 
        (a | b | c | ~d) &
        (a | b | ~c | d) &
        (a | ~b | c | d) &
        (a | ~b | ~c | ~d) &
        (~a | b | c | ~d) &
        (~a | b | ~c | d) &
        (~a | ~b | c | d) &
        (~a | ~b | ~c | ~d);

endmodule

