module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A=2'd0, B=2'd1, C=2'd2, D=2'd3, E=2'd4} state_t;

state_t current_state, next_state;
logic [1:0] w_count;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        w_count <= 2'd0;
    end else begin
        current_state <= next_state;
        w_count <= (current_state == B) ? (w_count + 1) : 2'd0;
    end
end

always_comb begin
    next_state = current_state;
    z = 1'b0;

    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end

        B: begin
            next_state = C;
        end

        C: begin
            if (w) begin
                w_count = w_count + 1;
            end
            next_state = D;
        end

        D: begin
            if (w) begin
                w_count = w_count + 1;
            end
            next_state = E;
        end

        E: begin
            if (w) begin
                w_count = w_count + 1;
            end
            next_state = B;
            if (w_count == 2'd2) begin
                z = 1'b1;
            end
        end

        default: next_state = A;
    endcase
end

endmodule

