module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Define the grid size
    localparam N = 16;

    // Internal state register
    reg [255:0] next_q;

    // Compute the next state of the grid
    always @(posedge clk) begin
        if (load) begin
            next_q <= data;
        end else begin
            next_q <= compute_next_state(q);
        end
    end

    // Output the current state
    assign q = next_q;

    // Function to compute the next state of the grid
    function [255:0] compute_next_state;
        input [255:0] current;
        reg [255:0] result;
        integer i, j, k, count;
        reg [3:0] neighbors;

        for (i = 0; i < N; i++) begin
            for (j = 0; j < N; j++) begin
                count = 0;
                for (k = 0; k < 8; k++) begin
                    // Define the 8 neighbor directions (dx, dy)
                    localparam DR = {2{2'b11}, 2'b00, 2'b00, 2'b11};
                    integer dx, dy;
                    dx = DR[k*2+1];
                    dy = DR[k*2];
                    integer x = (i + dx) % N;
                    integer y = (j + dy) % N;
                    if (current[(x * N) + y]) count = count + 1;
                end
                if (count == 0 || count == 1) begin
                    result[(i * N) + j] = 1'b0;
                end else if (count == 2) begin
                    result[(i * N) + j] = current[(i * N) + j];
                end else if (count == 3) begin
                    result[(i * N) + j] = 1'b1;
                end else begin
                    result[(i * N) + j] = 1'b0;
                end
            end
        end
        compute_next_state = result;
    endfunction

endmodule

module TopModule (
