    input  w,
    output Y1
);

    // State codes:
    // A = 000, B = 001, C = 010, D = 011, E = 100, F = 101

    // Define next_state as a reg (or logic) since it is assigned inside an always block
    reg next_state;

    // Next-state logic
    always @(y or w) begin
        if (w == 1'b0) begin
            if (y == 3'b000) next_state = 3'b000; // A -> A
            else if (y == 3'b001) next_state = 3'b000; // B -> A
            else if (y == 3'b010) next_state = 3'b100; // C -> E
            else if (y == 3'b011) next_state = 3'b100; // D -> E
            else if (y == 3'b100) next_state = 3'b100; // E -> E
            else if (y == 3'b101) next_state = 3'b100; // F -> E
        end else begin // w == 1'b1
            if (y == 3'b000) next_state = 3'b001; // A -> B
            else if (y == 3'b001) next_state = 3'b011; // B -> D
            else if (y == 3'b010) next_state = 3'b011; // C -> D
            else if (y == 3'b011) next_state = 3'b000; // D -> A
            else if (y == 3'b100) next_state = 3'b011; // E -> D
            else if (y == 3'b101) next_state = 3'b011; // F -> D
        end
    end

    // Output Y1 is y[1]
    assign Y1 = y[1];

endmodule

