    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state based on priority: fall > dig > direction change
            if (ground == 1'b0) begin
                // Falling
                next_state <= FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (dig == 1'b1) begin
                // Digging
                next_state <= DIGGING;
                digging <= 1'b1;
                aaah <= 1'b0;
            end else if (bump_left || bump_right) begin
                // Direction change
                if (bump_left) begin
                    next_state <= WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state <= WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end else begin
                // Continue current state
                next_state <= current_state;
            end
        end
    end

    // Output logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            case (next_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
