);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;
    reg current_direction; // 1 for left, 0 for right

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            current_direction <= 1;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state based on priority: fall > dig > direction change
            if (ground == 1'b0) begin
                // Falling
                next_state <= FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (dig == 1'b1) begin
                // Digging
                next_state <= DIGGING;
                digging <= 1'b1;
                aaah <= 1'b0;
            end else if (bump_left || bump_right) begin
                // Direction change
                if (bump_left) begin
                    next_state <= WALK_RIGHT;
                    current_direction <= 0;
                end else if (bump_right) begin
                    next_state <= WALK_LEFT;
                    current_direction <= 1;
                end
            end else begin
                // Continue current state
                next_state <= current_state;
            end
        end
    end

    // Output logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

    // Assign next_state
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,      // Below s[0]
        STATE_MID_LOW,  // Between s[1] and s[0]
        STATE_MID_HIGH, // Between s[2] and s[1]
        STATE_HIGH      // Above s[2]
    } state_t;

    state_t current_state, next_state;

    // State transition and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (current_state)
                STATE_LOW: begin
                    if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_MID_LOW: begin
                    if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_MID_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                default: begin
                    next_state <= STATE_LOW;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            current_state <= next_state;
        end
    end

endmodule

